function expandPath(id){if(!id)return;for(const n of R.path(id).slice(0,-1))if(!tree.expanded.includes(n.id))tree.expanded.push(n.id);saveTree();}
function paintTree(){const search=$('tree-search').value.toLocaleLowerCase('ru-RU'),active=current(),resolved=active?R.resolve(active.target,allRecords()):null,activeNode=resolved?.node||R.nodeFor(R.recipeTarget(active?.draft.craft?.recipeId||'')||{}),path=new Set(R.path(activeNode?.id).map(n=>n.id));const shown=new Set();if(search)for(const n of R.nodes)if(n.id!=='account'&&R.path(n.id)[0]?.id!=='account'&&CatalogMath.searchMatch(n.label,search))for(const p of R.path(n.id))shown.add(p.id);
 function row(n,depth){if(n.id==='account'||search&&!shown.has(n.id))return '';const children=n.children.filter(id=>R.byId.get(id)?.mode||R.byId.get(id)?.children.length),expanded=search?children.some(id=>shown.has(id)):tree.expanded.includes(n.id),selected=n.id===activeNode?.id;return '<div role="treeitem" data-tree-id="'+esc(n.id)+'" aria-level="'+(depth+1)+'" '+(children.length?'aria-expanded="'+expanded+'"':'')+' aria-selected="'+selected+'" tabindex="'+(selected?'0':'-1')+'" class="tree-row '+(selected?'active':path.has(n.id)?'active-parent':'')+'" style="--depth:'+depth+'"><button tabindex="-1" data-tree-toggle="'+esc(n.id)+'" aria-label="'+(expanded?'Свернуть ':'Раскрыть ')+esc(n.label)+'" '+(!children.length?'class="tree-spacer" disabled':'')+'>'+(children.length?(expanded?'▾':'▸'):'')+'</button><button tabindex="-1" data-tree-open="'+esc(n.id)+'" title="'+esc(n.label)+'">'+(depth===0?icon(n.mode||'gear'):'')+'<span>'+esc(n.label)+'</span></button>'+(children.length&&n.mode?'<button tabindex="-1" data-tree-overview="'+esc(n.id)+'" title="Открыть '+esc(n.label)+'" aria-label="Открыть '+esc(n.label)+'">↗</button>':'')+'</div>'+(expanded?children.map(id=>row(R.byId.get(id),depth+1)).join(''):'');}
 const focus=document.activeElement?.closest('[data-tree-id]')?.dataset.treeId,scroll=sidebar.scrollTop;$('navigation-tree').innerHTML=R.nodes.filter(n=>!n.parent).map(n=>row(n,0)).join('');const rows=$('navigation-tree').querySelectorAll('[role=treeitem]');if(![...rows].some(x=>x.tabIndex===0)&&rows[0])rows[0].tabIndex=0;sidebar.scrollTop=scroll;if(focus)document.querySelector('[data-tree-id="'+CSS.escape(focus)+'"]')?.focus({preventScroll:true});}
function toggleBranch(id,force){const expanded=tree.expanded.includes(id);tree.expanded=tree.expanded.filter(x=>x!==id);if(force===true||force===undefined&&!expanded)tree.expanded.push(id);saveTree();paintTree();}
$('navigation-tree').onclick=e=>{const toggle=e.target.closest('[data-tree-toggle]'),overview=e.target.closest('[data-tree-overview]'),b=e.target.closest('[data-tree-open]');if(toggle)toggleBranch(toggle.dataset.treeToggle);if(overview)open(R.section(overview.dataset.treeOverview));if(b){const n=R.byId.get(b.dataset.treeOpen);if(n.children.length)toggleBranch(n.id);else open(R.section(n.id));}};
$('navigation-tree').onkeydown=e=>{const row=e.target.closest('[role=treeitem]');if(!row)return;const n=R.byId.get(row.dataset.treeId),rows=[...$('navigation-tree').querySelectorAll('[role=treeitem]')],i=rows.indexOf(row);if(['ArrowDown','ArrowUp','ArrowLeft','ArrowRight','Enter',' '].includes(e.key))e.preventDefault();if(e.key==='ArrowDown')rows[Math.min(rows.length-1,i+1)]?.focus();if(e.key==='ArrowUp')rows[Math.max(0,i-1)]?.focus();if(e.key==='ArrowRight'){if(n.children.length&&!tree.expanded.includes(n.id))toggleBranch(n.id,true);else rows[i+1]?.focus();}if(e.key==='ArrowLeft'){if(n.children.length&&tree.expanded.includes(n.id))toggleBranch(n.id,false);else document.querySelector('[data-tree-id="'+CSS.escape(n.parent||'')+'"]')?.focus();}if(e.key==='Enter'){if(n.mode)open(R.section(n.id));else toggleBranch(n.id);}if(e.key===' ')toggleBranch(n.id);};
$('tree-search').oninput=paintTree;$('tree-collapse').onclick=()=>{tree.expanded=[];saveTree();paintTree();};
function paintPath(){const t=current(),resolved=t?R.resolve(t.target,allRecords()):null,node=resolved?.node||R.nodeFor(R.recipeTarget(t?.draft.craft?.recipeId||'')||{});$('workspace-path').innerHTML=R.path(node?.id).map(n=>'<button data-path="'+esc(n.id)+'">'+esc(n.label)+'</button>').join('<span aria-hidden="true">/</span>')+(t?.target.type==='saved'?'<span>/ '+esc(resolved.label||'Недоступно')+'</span>':'');}
$('workspace-path').onclick=e=>{const b=e.target.closest('[data-path]');if(!b)return;const n=R.byId.get(b.dataset.path);if(n.mode)open(R.section(n.id));else{setHidden(false);toggleBranch(n.id,true);document.querySelector('[data-tree-id="'+CSS.escape(n.id)+'"]')?.focus();}};
function setHidden(hidden){tree.hidden=hidden;document.body.classList.toggle('sidebar-collapsed',hidden);sidebar.inert=hidden;sidebar.setAttribute('aria-hidden',String(hidden));$('sidebar-toggle').setAttribute('aria-expanded',String(!hidden));saveTree();}
$('sidebar-toggle').onclick=()=>setHidden(!tree.hidden);$('navigation-close').onclick=()=>setHidden(true);sidebar.addEventListener('scroll',()=>{tree.scroll=sidebar.scrollTop;saveTree();});
function setWidth(width){tree.width=Math.max(220,Math.min(360,width));document.documentElement.style.setProperty('--navigation-width',tree.width+'px');resize.setAttribute('aria-valuenow',tree.width);resize.setAttribute('aria-valuemin','220');resize.setAttribute('aria-valuemax','360');saveTree();}
resize.onpointerdown=e=>{if(innerWidth<=1050)return;e.preventDefault();resize.setPointerCapture(e.pointerId);resize.onpointermove=x=>setWidth(x.clientX);resize.onpointerup=()=>resize.onpointermove=null;};resize.onkeydown=e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();setWidth(tree.width+(e.key==='ArrowLeft'?-10:10));}};
function currentSection(){const t=current(),node=t?R.resolve(t.target,allRecords()).node:null;return node?R.section(node.id):null;}
function hasFavorite(target){return target&&favorites.items.some(x=>W.targetKey(x.target)===W.targetKey(target));}
function paintStars(){const target=currentSection();$('favorite-section').hidden=!target;$('favorite-section').textContent=hasFavorite(target)?'★':'☆';$('favorite-section').setAttribute('aria-pressed',String(!!hasFavorite(target)));const item=R.recipeTarget(A.snapshot().recipe.id);itemStar.textContent=hasFavorite(item)?'★':'☆';itemStar.setAttribute('aria-pressed',String(!!hasFavorite(item)));}
function addFavorite(target,name,customName=false,context){if(favoriteError)return status(favoriteError);try{const x={id:uid(),target:W.target(target),name:String(name).slice(0,40),customName,...(context?{context}: {})};favorites=W.favorite(favorites,x);saveFavorites();return x.id;}catch(e){status(e.message);}}
function star(target){if(!target)return;const existing=favorites.items.find(x=>W.targetKey(x.target)===W.targetKey(target));if(existing){favorites={...favorites,items:favorites.items.filter(x=>x.id!==existing.id)};saveFavorites();return;}const resolved=R.resolve(target,allRecords()),defaultName=(resolved.label||target.id).slice(0,40);nameDialog('Добавить в избранное',defaultName,40,(name,pin)=>addFavorite(target,name,name!==defaultName,pin?{server:current().server,characterId:current().characterId}:undefined),'<label class="refining-check"><input type="checkbox" id="favorite-pin-context"> Закрепить текущий сервер и персонажа</label>');}
$('favorite-section').onclick=()=>star(currentSection());itemStar.onclick=()=>star(R.recipeTarget(A.snapshot().recipe.id));
function favoriteTitle(x){const resolved=R.resolve(x.target,allRecords());return x.customName?x.name:(resolved.label||x.name).slice(0,40);}
function paintFavorites(){const list=allFavorites?favorites.items:favorites.items.slice(0,6);$('favorite-empty').hidden=!!favorites.items.length;$('favorites-all').textContent=allFavorites?'Первые шесть':'Все избранные ('+favorites.items.length+')';$('favorite-list').innerHTML=list.map(x=>{const r=R.resolve(x.target,allRecords()),context=x.context?' · '+x.context.server+' / '+(profiles()?.profiles.find(p=>p.id===x.context.characterId)?.name||'Персонаж удалён'):'';return '<div class="favorite-row '+(!r.available?'unavailable':'')+'" data-favorite-id="'+esc(x.id)+'"><button class="favorite-handle" draggable="true" data-drag-favorite="'+esc(x.id)+'" aria-label="Изменить порядок '+esc(favoriteTitle(x))+'" title="Перетащить или открыть меню">⠿</button><button data-open-favorite="'+esc(x.id)+'" title="'+esc(favoriteTitle(x)+context)+'">'+icon(r.mode||'gear')+'<span>'+esc(favoriteTitle(x))+'<small>'+(!r.available?'Недоступно':x.target.type==='saved'?'Сохранённый крафт':x.target.type==='item'?'Предмет':'Раздел')+esc(context)+'</small></span></button><button class="favorite-more" data-favorite-menu="'+esc(x.id)+'" aria-label="Действия с '+esc(favoriteTitle(x))+'">⋮</button></div>';}).join('');}
function openFavorite(id,duplicate=false){const x=favorites.items.find(x=>x.id===id);if(x)open(x.target,{context:x.context,duplicate});}
function favoriteMenu(e,id){e.preventDefault();const x=favorites.items.find(x=>x.id===id);popover(e,[{label:'Открыть',run:()=>openFavorite(id)},{label:'Открыть в новой вкладке',run:()=>openFavorite(id,true)},{label:'Переименовать',run:()=>nameDialog('Название избранного',favoriteTitle(x),40,value=>{x.name=value;x.customName=true;saveFavorites();})},{label:'Переместить выше',run:()=>{favorites=W.move(favorites,id,-1);saveFavorites();}},{label:'Переместить ниже',run:()=>{favorites=W.move(favorites,id,1);saveFavorites();}},{label:'Убрать из избранного',run:()=>{favorites={...favorites,items:favorites.items.filter(x=>x.id!==id)};saveFavorites();}}]);}
$('favorites-all').onclick=()=>{allFavorites=!allFavorites;paintFavorites();};$('favorite-list').onclick=e=>{const b=e.target.closest('[data-open-favorite]'),m=e.target.closest('[data-favorite-menu],[data-drag-favorite]');if(b)openFavorite(b.dataset.openFavorite);if(m)favoriteMenu(e,m.dataset.favoriteMenu||m.dataset.dragFavorite);};$('favorite-list').oncontextmenu=e=>{const row=e.target.closest('[data-favorite-id]');if(row)favoriteMenu(e,row.dataset.favoriteId);};$('favorite-list').onkeydown=e=>{const row=e.target.closest('[data-favorite-id]');if(!row)return;if(e.altKey&&['ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();favorites=W.move(favorites,row.dataset.favoriteId,e.key==='ArrowUp'?-1:1);saveFavorites();document.querySelector('[data-drag-favorite="'+CSS.escape(row.dataset.favoriteId)+'"]')?.focus();}if(e.shiftKey&&e.key==='F10')favoriteMenu(e,row.dataset.favoriteId);};$('favorite-list').ondragstart=e=>{const b=e.target.closest('[data-drag-favorite]');if(b){dragFavorite=b.dataset.dragFavorite;e.dataTransfer.setData('text/plain',dragFavorite);}};$('favorite-list').ondragover=e=>e.preventDefault();$('favorite-list').ondrop=e=>{e.preventDefault();const row=e.target.closest('[data-favorite-id]');if(row&&dragFavorite){const from=favorites.items.findIndex(x=>x.id===dragFavorite),to=favorites.items.findIndex(x=>x.id===row.dataset.favoriteId);favorites=W.move(favorites,dragFavorite,to-from);saveFavorites();dragFavorite=null;}};
function libraryStars(){for(const button of document.querySelectorAll('[data-scenario-load]')){const id=button.dataset.scenarioLoad;if(button.parentElement.querySelector('[data-favorite-saved]')||!library().some(x=>x.id===id))continue;const b=document.createElement('button');b.className='button favorite-star';b.dataset.favoriteSaved=id;b.setAttribute('aria-label','Сохранённый крафт в избранном');b.textContent=hasFavorite({type:'saved',id})?'★':'☆';b.onclick=()=>star({type:'saved',id});button.before(b);const rename=document.createElement('button');rename.className='button';rename.textContent='Переименовать';rename.onclick=()=>nameDialog('Название сохранённого крафта',library().find(x=>x.id===id).name,80,value=>ScenarioUI.rename(id,value));button.after(rename);}}
new MutationObserver(()=>{libraryStars();paintFavorites();}).observe($('scenario-list'),{childList:true,subtree:true});
updateSaved.onclick=()=>{const t=current();if(t?.target.type==='saved')try{ScenarioUI.update(t.target.id,A.saveVariant());t.baseline=signature(A.saveVariant());t.libraryRevision=JSON.stringify(library().find(x=>x.id===t.target.id));t.dirty=false;save();paintTabs();status('Сохранённый крафт обновлён.');}catch(e){status(e.message);}};
function changeServer(server){if(!['europe','west','east'].includes(server))return;const t=current();if(!t)return;const previous=t.server;$('server').value=previous;capture();t.serverDrafts||={};t.serverDrafts[previous]=clone(t.draft);const draft=t.serverDrafts[server]?clone(t.serverDrafts[server]):clone(t.draft);if(!t.serverDrafts[server]){draft.craft.overrides={};draft.craft.config.manualSale=false;draft.craft.config.salePrice=0;for(const rows of Object.values(draft.craft.config.purchaseSplits||{}))if(Array.isArray(rows))for(const row of rows)row.price=null;if(Array.isArray(draft.craft.config.saleSplits))for(const row of draft.craft.config.saleSplits)row.price=null;if(draft.craft.config.singleSale){draft.craft.config.singleSale.manualSale=false;draft.craft.config.singleSale.salePrice=0;}draft.craft.config.journalEmptyPrice=null;draft.craft.config.journalFullPrice=null;if(['enchant','salvage','mounts'].includes(draft.mode)&&draft.feature)draft.feature.prices={};if(draft.mode==='training')for(const k of ['train-buy','train-sell'])draft.fields[k]='';if(draft.mode==='shipping'&&draft.feature)for(const item of draft.feature.plan.items){item.unitCosts||={};item.unitCosts[item.costServer||previous]=item.unitCost;item.unitCost=item.unitCosts[server]??null;item.costServer=server;}if(draft.mode==='deals'){draft.fields['deal-average']='';draft.fields['deal-fixed']='';}}t.draft=draft;t.server=server;$('server').value=server;activate(t.id,true);capture();status('Сервер активной вкладки изменён. Цены разделены по серверам.');}
