A.navigate=mode=>open(R.section(mode)||{type:'section',id:mode,mode});A.open=(id,patch={})=>{const target=R.recipeTarget(id);if(!target)return status('Предмет не найден.');open(target);if(Object.keys(patch).length)A.saveConfig(patch);};
A.restoreVariant=record=>{record=ScenarioMath.validate(record);const target=R.recipeTarget(record.recipeId);if(!target)throw Error('Предмет не найден.');open(target,{context:{server:record.server,characterId:record.characterId||profiles().active}});rawRestore(record);capture();paintTabs();paintPath();};
GameShell.collapsed=()=>tree.hidden;
$('reset').textContent='Сбросить параметры вкладки';$('reset').onclick=()=>{const t=current();if(!t||!['food','potions','gear','refine'].includes(t.draft.mode))return;capture();t.draft={craft:A.defaultDraft(A.snapshot().recipe.id),mode:t.draft.mode,feature:null,fields:{},scroll:0};t.serverDrafts={};activate(t.id,true);capture();status('Параметры активной вкладки сброшены.');};
