const serverHandler=$('server').onchange;$('server').onchange=()=>{const server=$('server').value;if(current())changeServer(server);else serverHandler();};
document.addEventListener('characterprofilechange',()=>{if(switching)return;const t=current();if(t){t.characterId=profiles()?.active||t.characterId;capture();paintTabs();paintFavorites();}});
function changed(){if(switching)return;clearTimeout(saveTimer);saveTimer=setTimeout(()=>{capture();paintTabs();paintPath();paintStars();},80);}
for(const event of ['input','change','craftdraftchange','masterychange','librarychange'])document.addEventListener(event,changed);
