$('workspace-replace-item').onclick=()=>itemChooser(true);$('workspace-replace-character').onclick=()=>{const t=current();if(t){t.characterId=profiles().active;t.unavailable=false;activate(t.id);}};
function selectedItem(){const t=current();if(!t)return null;const mode=activeMode();if(['food','potions','gear','refine'].includes(mode))return A.snapshot().recipe.id;const d=adapter(mode)?.captureDraft?.();return d?.item||d?.previewId||null;}
function selectItem(id,mode=activeMode(),newTab=false){const target=R.itemTarget(id,mode);if(!target)return status('Предмет не подходит этому разделу.');if(newTab)return open(target,{duplicate:true});const t=current();if(!t||t.draft.mode!==mode)return open(target);capture();const previous=selectedItem(),key=(item)=>[mode,item,t.server,t.characterId].join('|');if(previous===id)return t.id;t.itemDrafts||={};if(previous)t.itemDrafts[key(previous)]={target:clone(t.target),draft:clone(t.draft),baseline:t.baseline||null,libraryRevision:t.libraryRevision||null,dirty:!!t.dirty};const old=clone(t.draft),oldTarget=clone(t.target);try{const entry=t.itemDrafts[key(id)];t.draft=entry?clone(entry.draft):createDraft(R.resolve(target,allRecords()),t.server,t.draft.craft);t.target=entry?clone(entry.target):target;t.baseline=entry?.baseline||null;t.libraryRevision=entry?.libraryRevision||null;t.dirty=!!entry?.dirty;t.unavailable=false;activate(t.id,true);capture();return t.id;}catch(e){switching=false;t.target=oldTarget;t.draft=old;activate(t.id,true);status(e.message);}}
window.Workspace={selectItem,selectedItem,activeMode,open,activate,close,reopen,tabAction,capture,changeServer,registry:R,snapshot:()=>clone(data),favorites:()=>clone(favorites),addFavorite,removeFavorite(id){favorites={...favorites,items:favorites.items.filter(x=>x.id!==id)};saveFavorites();},moveFavorite(id,offset){favorites=W.move(favorites,id,offset);saveFavorites();},setHidden,setWidth,tree:()=>clone(tree),ticket:()=>({tabId:data.active,server:current()?.server,epoch}),accept:t=>t.tabId===data.active&&t.server===current()?.server&&t.epoch===epoch};
if(!data){const characterId=profiles()?.active||'primary',mode=activeMode(),target=R.section(mode)||R.recipeTarget(initialCraft.recipeId);data=W.empty();data=W.open(data,{id:uid(),target,server:$('server').value,characterId,name:'',pinned:false,draft:{craft:initialCraft,mode,feature:adapter(mode)?.captureDraft?.()||null,fields:formCapture(panelFor(mode)),scroll:0}},true);}
setWidth(tree.width);setHidden(tree.hidden);activate(data.active,true);paintFavorites();libraryStars();sidebar.scrollTop=initialScroll;
